package cn.huankan.collector;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
class MacroAdaptersTest {
    byte[] xml(String title,String url,String time){return ("<?xml version=\"1.0\" encoding=\"UTF-8\"?><rss><channel><item><title>"+title+"</title><link>"+url+"</link><pubDate>"+time+"</pubDate></item></channel></rss>").getBytes(StandardCharsets.UTF_8);}
    @Test void nbsPreservesChineseAndBeijingTime(){var bytes=xml("隔离测试CPI","https://www.stats.gov.cn/sj/zxfb/fixture.html","2026-10-09 09:30:00");var result=NbsCollector.segments(bytes).getFirst();assertEquals("隔离测试CPI",result.item().title());assertEquals(Instant.parse("2026-10-09T01:30:00Z"),result.item().publishedAt());assertEquals(result.item().url(),result.item().documentId());assertTrue(new String(bytes,StandardCharsets.UTF_8).contains(new String(result.bytes(),StandardCharsets.UTF_8)));}
    @Test void nbsRejectsForeignSource(){assertThrows(IllegalArgumentException.class,()->NbsCollector.segments(xml("隔离","https://www.stats.gov.cn.evil.invalid/a","2026-10-09 09:30:00")));}
    @Test void nbsRejectsInvalidCalendarDate(){assertThrows(IllegalArgumentException.class,()->NbsCollector.segments(xml("隔离","https://www.stats.gov.cn/a","2026-02-30 09:30:00")));}
    @Test void nbsRejectsExternalEntities(){assertThrows(IllegalArgumentException.class,()->NbsCollector.segments("<?xml version=\"1.0\" encoding=\"UTF-8\"?><!DOCTYPE rss SYSTEM 'file:///isolated'><rss/>".getBytes(StandardCharsets.UTF_8)));}
    @Test void nbsRejectsUnknownEncoding(){assertThrows(IllegalArgumentException.class,()->NbsCollector.segments("<?xml version=\"1.0\" encoding=\"GBK\"?><rss/>".getBytes(StandardCharsets.UTF_8)));}
    String header="KEY,FREQ,CURRENCY,CURRENCY_DENOM,EXR_TYPE,EXR_SUFFIX,TIME_PERIOD,OBS_VALUE,OBS_STATUS,UNIT,UNIT_MULT,TITLE\n";
    byte[] csv(String currency,String date,String value,String unit){return (header+"EXR.D."+currency+".EUR.SP00.A,D,"+currency+",EUR,SP00,A,"+date+","+value+",A,"+unit+",0,\"isolated, reference\"\n").getBytes(StandardCharsets.UTF_8);}
    @Test void sdmxPreservesNumericPrecisionAndQuotedComma(){var obs=SdmxCsv.parse(csv("USD","2026-09-01","1.1590","USD"),"EXR.D.USD.EUR.SP00.A").getFirst();assertEquals("1.1590",obs.value().toPlainString());assertEquals("isolated, reference",obs.metadata().get("TITLE"));}
    @Test void sdmxRejectsWrongSeries(){assertThrows(IllegalArgumentException.class,()->SdmxCsv.parse(csv("JPY","2026-09-01","170","JPY"),"EXR.D.USD.EUR.SP00.A"));}
    @Test void sdmxRejectsWrongUnits(){assertThrows(IllegalArgumentException.class,()->SdmxCsv.parse(csv("USD","2026-09-01","1.1","JPY"),"EXR.D.USD.EUR.SP00.A"));}
    @Test void sdmxMissingValueIsNotZero(){assertNull(SdmxCsv.parse(csv("USD","2026-09-01","","USD"),"EXR.D.USD.EUR.SP00.A").getFirst().value());}
    @Test void sdmxRejectsFutureObservations(){assertThrows(IllegalArgumentException.class,()->SdmxCsv.parse(csv("USD","2099-09-01","1.1","USD"),"EXR.D.USD.EUR.SP00.A"));}
    @Test void sdmxRejectsDuplicateDateAndMalformedQuotes(){var data=new String(csv("USD","2026-09-01","1.1","USD"),StandardCharsets.UTF_8);assertThrows(IllegalArgumentException.class,()->SdmxCsv.parse((data+data.substring(header.length())).getBytes(StandardCharsets.UTF_8),"EXR.D.USD.EUR.SP00.A"));assertThrows(IllegalArgumentException.class,()->SdmxCsv.rows("\"unterminated"));}
    @Test void officialWhitelistBlocksArbitraryQueries(){OfficialHttpClient.validate(java.net.URI.create("https://www.stats.gov.cn/sj/zxfb/rss.xml"));OfficialHttpClient.validate(java.net.URI.create("https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A?startPeriod=2026-09-01&format=csvdata"));assertThrows(IllegalArgumentException.class,()->OfficialHttpClient.validate(java.net.URI.create("https://data-api.ecb.europa.eu/service/data/EXR/D.USD.EUR.SP00.A?evil=1")));}
    @Test void policyRatePreservesAnnualPercentageAndChangeDate(){String raw="KEY,FREQ,REF_AREA,CURRENCY,PROVIDER_FM,INSTRUMENT_FM,PROVIDER_FM_ID,DATA_TYPE_FM,TIME_PERIOD,OBS_VALUE,OBS_STATUS,UNIT,UNIT_MULT,TITLE\nFM.B.U2.EUR.4F.KR.DFR.LEV,B,U2,EUR,4F,KR,DFR,LEV,2026-09-16,2.5,A,PCPA,0,isolated policy\n";var obs=SdmxCsv.parse(raw.getBytes(StandardCharsets.UTF_8),"FM.B.U2.EUR.4F.KR.DFR.LEV").getFirst();assertEquals("2.5",obs.value().toPlainString());assertEquals("PCPA",obs.metadata().get("UNIT"));assertThrows(IllegalArgumentException.class,()->SdmxCsv.parse(raw.replace("PCPA","USD").getBytes(StandardCharsets.UTF_8),"FM.B.U2.EUR.4F.KR.DFR.LEV"));}
    @Test void namespaceLimitsDimensionsToOfficialStructure(){String xml="<mes:Structure xmlns:mes='http://www.sdmx.org/resources/sdmxml/schemas/v2_1/message' xmlns:str='http://www.sdmx.org/resources/sdmxml/schemas/v2_1/structure'><str:Dataflow id='EXR' agencyID='ECB'/><str:DataStructure id='ECB_EXR1'><annotation><Dimension/></annotation><str:DimensionList>";int position=0;for(String id:java.util.List.of("FREQ","CURRENCY","CURRENCY_DENOM","EXR_TYPE","EXR_SUFFIX"))xml+="<str:Dimension id='"+id+"' position='"+(++position)+"'/>";xml+="</str:DimensionList></str:DataStructure></mes:Structure>";SdmxCsv.validateStructure(xml.getBytes(StandardCharsets.UTF_8));assertThrows(IllegalArgumentException.class,()->SdmxCsv.validateStructure("<rss/>".getBytes(StandardCharsets.UTF_8)));}
}
